    39→      roomId,
    40→      roomName: room.displayName(),
    41→    });
    42→  };
    43→
    44→  const handleInviteAccepted = () => {
    45→    setIsInviteAccepted(true);
    46→  };
    47→
    48→  const handleInviteDeclined = () => {
    49→    navigation.goBack();
    50→  };
    51→
    52→  const handleRoomDetails = () => {
    53→    if (isRoomInvite || !room) return;
    54→    navigation.navigate("roomDetails", { room });
    55→  };
